"""Generate register constants and documentation from the canonical JSON input."""

import argparse
import json
import re
import sys
from pathlib import Path

IP = Path(__file__).resolve().parents[1]


def products(schema: dict) -> dict[Path, str]:
    if (
        schema["schema_version"] != 2
        or schema["apb"] != "APB4"
        or schema["data_width"] != 32
        or schema["channel_base"] != 65536
        or schema["channel_stride"] != 65536
        or schema["channels_max"] != 2
    ):
        raise ValueError("unsupported register contract")
    sv = [
        "// Generated by tools/generate.py; edit config/contracts/registers.json.",
        "// Consumers intentionally use subsets of the complete register constant API.",
        "/* verilator lint_off UNUSEDPARAM */",
        "package lpddr5_mc_register_pkg;",
    ]
    header = [
        "/* Generated by tools/generate.py; edit config/contracts/registers.json. */",
        "#pragma once",
        "#include <stdint.h>",
    ]
    doc = [
        "# Register contract",
        "",
        "Generated from [registers.json](../../config/contracts/registers.json). "
        "See [control and recovery](../spec/control.md) "
        "for atomic publication, APB4 errors, ownership and clock crossings.",
        "",
        "Shared addresses are absolute. Channel offsets add `0x10000 + channel * 0x10000`. "
        "RW configuration fields write staging state; mailbox RW fields hold the next command payload. "
        "Active state is identified by CONFIG_EPOCH. Unlisted bits read zero and ignore writes. "
        "All counters saturate. Snapshot captures both halves of every performance counter together.",
        "",
        "| Name | Scope / offset | Reset | Lock | Owner / CDC | Fields (lsb:width access unit) |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for name in ("channel_base", "channel_stride"):
        sv.append(f"  localparam logic [31:0] LPDDR5_MC_{name.upper()} = 32'h{schema[name]:08x};")
        header.append(f"#define LPDDR5_MC_{name.upper()} UINT32_C(0x{schema[name]:08x})")
    addresses: set[tuple[str, int]] = set()
    names: set[str] = set()
    for reg in schema["registers"]:
        if (
            set(reg) != {"name", "offset", "scope", "lock", "owner", "cdc", "reset", "fields"}
            or not re.fullmatch(r"[A-Z][A-Z0-9_]*", reg["name"])
            or reg["scope"] not in ("shared", "channel")
            or reg["lock"] not in ("none", "disabled", "quiesced", "inactive_or_quiesced")
            or not reg["owner"]
            or not reg["cdc"]
            or type(reg["offset"]) is not int
            or not 0 <= reg["offset"] < 65536
            or type(reg["reset"]) is not int
            or not 0 <= reg["reset"] < 1 << 32
        ):
            raise ValueError("register metadata")
        address = (reg["scope"], reg["offset"])
        if address in addresses or reg["name"] in names or reg["offset"] % 4:
            raise ValueError("duplicate or misaligned register")
        addresses.add(address)
        names.add(reg["name"])
        used = 0
        field_names = set()
        for field in reg["fields"]:
            if (
                set(field) != {"name", "lsb", "width", "access", "unit", "description"}
                or field["name"] in field_names
                or not re.fullmatch(r"[A-Z][A-Z0-9_]*", field["name"])
                or not field["unit"]
                or not field["description"]
            ):
                raise ValueError("field metadata")
            field_names.add(field["name"])
            if (
                type(field["width"]) is not int
                or type(field["lsb"]) is not int
                or not 0 < field["width"] <= 32
                or not 0 <= field["lsb"] <= 32 - field["width"]
            ):
                raise ValueError("field outside register")
            mask = ((1 << field["width"]) - 1) << field["lsb"]
            if used & mask or field["access"] not in {"ro", "rw", "w1c", "w1s"}:
                raise ValueError("overlap or unsupported access")
            used |= mask
            name = "LPDDR5_MC_" + reg["name"] + "_" + field["name"] + "_MASK"
            sv.append(f"  localparam logic [31:0] {name} = 32'h{mask:08x};")
            header.append(f"#define {name} UINT32_C(0x{mask:08x})")
        if reg["reset"] & ~used:
            raise ValueError("reset sets reserved bits")
        name = "LPDDR5_MC_" + reg["name"]
        sv.append(f"  localparam logic [31:0] {name} = 32'h{reg['offset']:08x};")
        header.append(f"#define {name} UINT32_C(0x{reg['offset']:08x})")
        fields = "; ".join(
            f"{f['name']} ({f['lsb']}:{f['width']} {f['access']} {f['unit']}): {f['description']}"
            for f in reg["fields"]
        )
        doc.append(
            f"| {reg['name']} | {reg['scope']} / 0x{reg['offset']:04x} | 0x{reg['reset']:08x} "
            f"| {reg['lock']} | {reg['owner']} / {reg['cdc']} | {fields} |"
        )
    sv.extend(["endpackage", "/* verilator lint_on UNUSEDPARAM */"])
    return {
        IP / "rtl/generated/lpddr5_mc_register_pkg.sv": "\n".join(sv) + "\n",
        IP / "sw/generated/lpddr5_mc_registers.h": "\n".join(header) + "\n",
        IP / "docs/programming/registers.md": "\n".join(doc) + "\n",
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    sys.path.insert(0, str(IP / "dv"))
    from contracts.configuration import example_configuration, register_image, validate_register_image

    schema = json.loads((IP / "config/contracts/registers.json").read_text())
    profile = json.loads((IP / "config/contracts/profiles.json").read_text())["profiles"][0]
    config = example_configuration()
    image = register_image(schema, profile, config)
    validate_register_image(image, profile, config, schema)
    generated = products(schema)
    generated[IP / "config/generated/example-register-image.json"] = json.dumps(image, indent=2) + "\n"
    for path, content in generated.items():
        if args.check:
            if not path.exists() or path.read_text() != content:
                raise SystemExit("stale generated artifact: " + str(path.relative_to(IP)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)


if __name__ == "__main__":
    main()
